import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import format_timesheet


def make(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make("Ana", "mon", 540, 600),
            make("Brisa", "mon", 540, 720),
            make("Brisa", "tue", 540, 630)
        ]
        self.assertEqual(
            format_timesheet(shifts),
            [
                "Brisa: 2 shifts, 4.5 hours",
                "Ana: 1 shifts, 1.0 hours"
            ]
        )

    def test_empty(self):
        with self.assertRaises(ValueError):
            format_timesheet([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            format_timesheet([make(" ", "mon", 0, 60)])
